#include <bits/stdc++.h>
using namespace std;

int main() {
    long long a, b, sum1 = 0, sum2 = 0;
    vector<long long> v1, v2;

    cin >> a >> b;

    while (a / 10 != 0) {
        if (a % 10 != 0)
            v1.push_back(a % 10);
        a /= 10;
    }

    while (b / 10 != 0) {
        if (b % 10 != 0)
            v2.push_back(b % 10);
        b /= 10;
    }

    for (long long digit : v1)
        sum1 += digit;

    for (long long digit : v2)
        sum2 += digit;

    if (sum1 + sum2 == a + b)
        cout << "YES";
    else
        cout << "NO";

    return 0;
}

